export const FAQ_PUBLICA: readonly { clave: string; tema: string; es: readonly [string, string]; en: readonly [string, string] }[] = [{"clave":"ciudades","tema":"general","es":["¿En qué ciudades prestan el servicio?","Estamos en Bogotá, en Pontevedra (atendemos con cita), y hacemos eventos en todo el país."],"en":["Which cities do you work in?","We are based in Bogotá (Pontevedra, by appointment) and serve events across the country."]},{"clave":"idiomas","tema":"general","es":["¿En qué idiomas trabajan?","Español, portugués e inglés."],"en":["Which languages do you work in?","Spanish, Portuguese and English."]},{"clave":"publico","tema":"general","es":["¿Trabajan solo con empresas?","No. Trabajamos con empresas, colegios, universidades y otras organizaciones."],"en":["Do you only work with companies?","No. We work with companies, schools, universities and other organizations."]},{"clave":"combinar","tema":"general","es":["¿Puedo contratar varios servicios para un mismo evento?","Sí. Los servicios se contratan por separado o como un solo evento, con un solo equipo a cargo."],"en":["Can I book several services for the same event?","Yes. Services can be booked separately or as a single event, with one team in charge."]},{"clave":"virtual","tema":"formaciones","es":["¿Las formaciones pueden ser virtuales?","Sí. Las actividades digitales funcionan en sala, en campo o por videollamada."],"en":["Can the training be virtual?","Yes. The digital activities work in a room, in the field or on a video call."]},{"clave":"colegios","tema":"formaciones","es":["¿Tienen formaciones para colegios?","Sí. Hacemos orientación vocacional e inclusión con metodología vivencial para colegios y universidades."],"en":["Do you offer training for schools?","Yes. We run career guidance and inclusion programs with an experiential method for schools and universities."]},{"clave":"calidad-video","tema":"audiovisual","es":["¿En qué calidad entregan los videos?","Entregamos en calidad 4K y podemos sumar tomas aéreas con dron."],"en":["What quality do you deliver videos in?","We deliver in 4K and can add aerial drone footage."]},{"clave":"cobertura-catering","tema":"catering","es":["¿El catering tiene cobertura nacional?","Sí. Atendemos eventos empresariales, académicos y sociales en todo el país, con logística flexible."],"en":["Is the catering available nationwide?","Yes. We serve corporate, academic and social events across the country, with flexible logistics."]},{"clave":"diseno-proceso","tema":"diseno","es":["¿Pueden llevar una idea hasta el producto final?","Sí. Acompañamos desde el prototipo hasta el producto funcional, con la identidad de tu marca."],"en":["Can you take an idea all the way to a finished product?","Yes. We work from the prototype to the functional product, with your brand’s identity."]},{"clave":"ia-quien","tema":"ia","es":["¿Quién dicta la capacitación en IA?","Antídoto diseña y ofrece la capacitación, con su metodología vivencial y la logística a cargo del mismo equipo."],"en":["Who teaches the AI training?","Antídoto designs and delivers the training, with its experiential method and the logistics handled by the same team."]},{"clave":"ia-herramienta","tema":"ia","es":["¿Con qué herramienta trabajamos?","Con la que tu empresa ya usa o piensa usar: Claude, Gemini, ChatGPT o Copilot. Si todavía no hay una definida, la capacitación ayuda a elegir."],"en":["Which tool do we work with?","The one your company already uses or plans to use: Claude, Gemini, ChatGPT or Copilot. If none is chosen yet, the training helps you decide."]},{"clave":"ia-a-medida","tema":"ia","es":["¿La capacitación se adapta a mi área?","Sí. Los ejercicios se arman con documentos y procesos parecidos a los de tu equipo, ya sea talento humano, SST, comunicaciones, finanzas o educación."],"en":["Is the training tailored to my team?","Yes. The exercises are built with documents and processes similar to your team’s, whether HR, health and safety, communications, finance or education."]},{"clave":"ia-datos","tema":"ia","es":["¿Qué pasa con la información confidencial de la empresa?","Es parte del programa: el equipo aprende qué datos no se entregan a un asistente de IA y cómo revisar lo que responde antes de usarlo."],"en":["What about the company’s confidential information?","It is part of the program: the team learns which data never goes into an AI assistant and how to check its answers before using them."]},{"clave":"como-cotizar","tema":"cotizacion","es":["¿Cómo pido una cotización?","Con el cotizador del sitio: eliges el servicio, la fecha y el tamaño del grupo, y envías el mensaje por WhatsApp o por correo. También puedes llamarnos."],"en":["How do I request a quote?","With the quote builder on this site: choose the service, the date and the group size, and send the message on WhatsApp or by email. You can also call us."]}];
